import { buildNodeConfig, escapeHTML, githubPrUrl, nodeStatus, validateNodeConfig } from './onboarding.mjs';
const root=document.querySelector('#app');
const state={page:'tasks',user:null,csrf:'',items:{projects:[],tasks:[],connections:[],nodes:[],members:[],teams:[],audit:[]},capabilities:null,detail:null,busy:false,filter:'all',search:'',modal:null,bootstrap:false,tab:'all',toolFilter:'all',selected:new Set(),detailTab:'plan',transferIds:[],nodeSetup:null,selectedNode:null};
const nav=[['tasks','任务'],['projects','项目'],['connections','工具连接'],['nodes','执行节点'],['members','成员与共享'],['audit','操作记录']];
const idOf=x=>x?.id??x?.taskId??x?.projectId??x?.nodeId??x?.connectionId??'';
const listOf=x=>Array.isArray(x)?x:Array.isArray(x?.items)?x.items:Array.isArray(x?.data)?x.data:[];
const tag=(text,color='')=>`<span class="badge ${color}">${escapeHTML(text||'未知状态')}</span>`;
function statusColor(status){return ({running:'blue',planning:'blue',queued:'',awaiting_approval:'orange',stopping:'orange',awaiting_review:'purple',completed:'green',failed:'red',blocked:'red',quota_blocked:'orange',offline:'',online:'green'})[status]||''}
const findById=(list,id)=>list.find(x=>idOf(x)===id);
const memberName=id=>findById(state.items.members,id)?.name||'—';
const connectionOf=id=>findById(state.items.connections,id);
const nodeOf=id=>findById(state.items.nodes,id);
const toolLabel=t=>({codex:'Codex',cursor:'Cursor'}[t]||t||'未分配');
function githubPrLink(value){const url=githubPrUrl(value);return url?`<p><a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">打开 GitHub PR ↗</a></p>`:''}
const toolIcon=t=>`<span class="tool"><span class="toolicon ${t==='cursor'?'cursor':''}">${t==='cursor'?'↗':'⌘'}</span>${escapeHTML(toolLabel(t))}</span>`;
const shortId=id=>String(id||'').slice(0,8);
const roleName=r=>r==='admin'?'组织管理员':'成员';
const canTransfer=t=>['running','queued','quota_blocked'].includes(t.status);
const taskNodeId=t=>connectionOf(t.connectionId)?.nodeId||'';
function statusName(status){return ({running:'执行中',planning:'规划中',planning_queued:'等待规划',queued:'排队中',awaiting_approval:'待确认',stopping:'转交中',awaiting_review:'待验收',completed:'已完成',failed:'失败',blocked:'等待处理',quota_blocked:'额度耗尽',quota_exhausted:'额度耗尽',online:'在线',offline:'离线'})[status]||status||'未知'}
function toast(message,error=false){const host=document.querySelector('#toast');host.innerHTML=`<div class="toast ${error?'error':''}">${escapeHTML(message)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>host.replaceChildren(),3600)}
async function api(path,{method='GET',body,auth=true,headers={}}={}){
 const h={Accept:'application/json',...headers};
 if(body!==undefined)h['Content-Type']='application/json';
 if(auth&&method!=='GET'&&state.csrf)h['X-CSRF-Token']=state.csrf;
 const response=await fetch('/api/v1'+path,{method,credentials:'same-origin',headers:h,body:body===undefined?undefined:JSON.stringify(body)});
 const raw=await response.text();let result={};try{result=raw?JSON.parse(raw):{}}catch{throw new Error(`服务器返回了无效响应 (${response.status})`)}
 if(!response.ok){const error=new Error(result.error?.message||result.message||`请求失败 (${response.status})`);error.status=response.status;throw error}
 return result.data??result;
}
async function boot(){try{const response=await api('/auth/status',{auth:false});if(response.needsBootstrap){state.bootstrap=true;render();return}const me=await api('/auth/me');state.user=me.user;state.csrf=me.csrfToken||'';await refresh();render()}catch(error){if(error.status===401||error.message?.includes('未登录')){state.user=null;render()}else renderError(error)}}
async function refresh(){
 const routes={projects:'/projects',tasks:'/tasks',connections:'/connections',nodes:'/nodes',members:'/members',teams:'/teams',audit:'/audit'};
 const entries=await Promise.all(Object.entries(routes).map(async([key,path])=>{try{return[key,listOf(await api(path))]}catch(error){if(error.status===403||error.status===404)return[key,[]];throw error}}));
 state.items=Object.fromEntries(entries);
}
function render(){
 if(state.bootstrap){renderAuth(true);return}
 if(!state.user){renderAuth(false);return}
 const labels=Object.fromEntries(nav);
 const icons={tasks:'▤',projects:'▦',connections:'⌘',nodes:'▣',members:'♧',audit:'◷'};
 const counts={tasks:state.items.tasks.length,projects:state.items.projects.length,connections:state.items.connections.length,nodes:state.items.nodes.length};
 const groups=[['工作空间',['tasks','projects']],['工作资源',['connections','nodes']],['组织管理',['members','audit']]];
 const active=state.page==='detail'?'tasks':state.page;
 const navHtml=groups.map(([title,keys])=>`<div class="navtitle">${title}</div>`+keys.map(key=>`<button class="nav ${active===key?'active':''}" data-page="${key}"><span class="ico">${icons[key]}</span><span>${labels[key]}</span>${counts[key]==null?'':`<span class="num">${counts[key]}</span>`}</button>`).join('')).join('');
 const org=state.user.organization||'团队工作区';
 const online=state.items.nodes.filter(n=>n.status==='online').length;
 const initial=escapeHTML((state.user.name||'?').slice(0,1));
 root.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><b class="logo">g</b><span>gas town<span style="color:#a3aab5">.</span></span></div><div class="org"><span class="avatar">${escapeHTML(org.slice(0,1))}</span><div style="flex:1"><b style="font-size:12px">${escapeHTML(org)}</b><div class="tiny" style="margin:0">私有部署 · 成员隔离</div></div></div>${navHtml}<div class="sidebar-bottom"><div class="nodehealth"><span class="dot ${online?'':'gray'}"></span>${online?`${online} 台执行节点在线`:'等待执行节点连接'}</div><div class="user"><span class="avatar">${initial}</span><div><b style="font-size:12px">${escapeHTML(state.user.name||state.user.email)}</b><div class="tiny" style="margin:0">${roleName(state.user.role)}</div></div><button class="quiet" data-action="logout" aria-label="退出登录">退出</button></div></div></aside><main class="main"><header class="topbar"><span>${escapeHTML(org)} / ${state.page==='detail'?'任务详情':labels[state.page]||'任务中心'}</span><button class="quiet" data-action="refresh">刷新</button></header><div class="content">${state.page==='detail'?taskDetail():pageBody()}</div></main></div>${state.modal?renderModal():''}`;
 bind();
}
function renderAuth(bootstrap){const title=bootstrap?'创建团队管理员':'登录团队工作区';root.innerHTML=`<main class="center panel"><h1>${title}</h1><p class="sub">${bootstrap?'首次设置组织；管理员账号只创建一次。':'使用组织管理员为你创建的账号登录。'}</p><form class="form" id="auth-form">${bootstrap?field('organization','组织名称','Freud 团队')+field('name','你的姓名'):' '+''}${field('email','邮箱','', 'email')}${field('password','密码','', 'password')}${bootstrap?field('confirm','再次输入密码','', 'password'):''}<button class="primary" type="submit">${bootstrap?'创建组织':'登录'}</button><div id="form-error" role="alert"></div></form></main>`;document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));if(bootstrap&&values.password!==values.confirm){formError('两次密码不一致');return}try{state.busy=true;const path=bootstrap?'/auth/bootstrap':'/auth/login';const data=await api(path,{method:'POST',auth:false,body:bootstrap?{organization:values.organization,name:values.name,email:values.email,password:values.password}:{email:values.email,password:values.password}});state.user=data.user;state.csrf=data.csrfToken||'';state.bootstrap=false;await refresh();render()}catch(error){formError(error.message)}}}
function formError(message){const el=document.querySelector('#form-error');if(el)el.innerHTML=`<div class="callout error">${escapeHTML(message)}</div>`}
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" ${extra} required></div>`}
function title(head,description,actions=''){return `<div class="titlebar"><div><h1>${head}</h1><div class="sub">${description}</div></div><div class="actions">${actions}</div></div>`}
function empty(head,copy,button=''){return `<div class="empty"><h2>${head}</h2><p>${copy}</p>${button}</div>`}
function pageBody(){switch(state.page){case'tasks':return tasksPage();case'projects':return projectsPage();case'connections':return connectionsPage();case'nodes':return nodesPage();case'members':return membersPage();case'audit':return auditPage();default:return tasksPage()}}
function tasksPage(){
 const tasks=filteredTasks();
 const running=state.items.tasks.filter(t=>t.status==='running');
 const waiting=state.items.tasks.filter(t=>t.status==='awaiting_approval'||t.status==='awaiting_review');
 const online=state.items.nodes.filter(n=>n.status==='online');
 const delivered=state.items.tasks.filter(t=>t.status==='completed'&&t.updatedAt&&Date.now()-new Date(t.updatedAt).getTime()<7*864e5);
 const blocked=state.items.tasks.filter(t=>t.status==='quota_blocked');
 const tools=new Set(running.map(t=>t.tool));
 const tabs=[['all','全部任务'],['running','执行中'],['approval','待确认'],['review','待验收']];
 const banner=blocked.length?`<div class="alert"><span class="alert-icon">!</span><span><b>${escapeHTML(toolLabel(blocked[0].tool))} 已报告额度耗尽</b> ${blocked.length} 个任务可以转交，保留当前代码与任务进度。</span><button data-action="quick-transfer">转交给其他工具 →</button></div>`:'';
 const rows=tasks.map(t=>{
  const project=findById(state.items.projects,t.projectId);
  const checked=state.selected.has(idOf(t));
  const box=canTransfer(t)?`<input type="checkbox" data-select="${escapeHTML(idOf(t))}" ${checked?'checked':''} aria-label="选择任务">`:'';
  return `<tr class="taskrow ${checked?'selected':''}"><td>${box}</td><td><button class="taskname" data-task="${escapeHTML(idOf(t))}">${escapeHTML(t.title)}</button><div class="taskmeta">${escapeHTML(shortId(idOf(t)))} · ${escapeHTML(project?.name||'项目')}</div></td><td>${tag(statusName(t.status),statusColor(t.status))}</td><td>${toolIcon(t.tool)}<div class="tiny">${escapeHTML(t.model||'')}</div></td><td><span class="avatar">${escapeHTML(memberName(t.ownerId).slice(0,1))}</span> ${escapeHTML(memberName(t.ownerId))}</td></tr>`;
 }).join('');
 const table=tasks.length?`<div class="wrap"><table><thead><tr><th></th><th>任务</th><th>状态</th><th>工具 / 模型</th><th>负责人</th></tr></thead><tbody>${rows}</tbody></table></div><div class="tablefoot"><span>${state.selected.size?`已选 ${state.selected.size} 项`:'选择可转交的任务'}</span>${state.selected.size?`<button class="small" data-action="transfer-selected">转交所选</button>`:''}</div>`:empty(state.items.tasks.length?'没有符合条件的任务':'还没有任务',state.items.tasks.length?'调整筛选条件。':'创建任务后，执行节点会先生成计划，等你确认再开工。',state.items.projects.length&&state.items.connections.length?'<button class="primary" data-action="new-task">新建任务</button>':'');
 return title('让工作持续向前','统一下发任务，随时掌握每个 Agent 的执行状态。','<button data-action="open-policy">接管策略</button><button class="primary" data-action="new-task">＋ 新建任务</button>')+`<div class="metrics"><div class="metric"><div class="metriclabel">正在执行</div><div class="metricvalue">${running.length}<span style="font-size:12px;font-weight:400;color:var(--muted);margin-left:9px"> 个任务</span></div><div class="metricfoot"><span class="dot blue"></span>${tools.size||0} 种工具在执行</div></div><div class="metric"><div class="metriclabel">等待你的确认</div><div class="metricvalue">${waiting.length}</div><div class="metricfoot">执行计划与 PR 验收</div></div><div class="metric"><div class="metriclabel">可用执行节点</div><div class="metricvalue">${online.length}<span style="font-size:15px;font-weight:400;color:#a4aab4"> / ${state.items.nodes.length}</span></div><div class="metricfoot"><span class="dot ${online.length?'':'gray'}"></span>个人电脑与团队服务器</div></div><div class="metric"><div class="metriclabel">本周已交付</div><div class="metricvalue">${delivered.length}</div><div class="metricfoot">已完成，等待或已经人工验收</div></div></div>${banner}<div class="grid"><section class="panel"><div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${state.tab===k?'active':''}" data-tab="${k}">${l}</button>`).join('')}</div><div class="filters"><input id="task-search" class="search" placeholder="搜索任务名称或编号" value="${escapeHTML(state.search)}"><select id="tool-filter" class="select"><option value="all">全部工具</option>${['codex','cursor'].map(t=>`<option value="${t}" ${state.toolFilter===t?'selected':''}>${toolLabel(t)}</option>`).join('')}</select><span class="sub" style="margin-left:auto">按最近活动排序</span></div>${table}</section><aside class="panel">${rail()}</aside></div>`;
}
function filteredTasks(){
 const tab={all:()=>true,running:t=>['running','planning','planning_queued','queued','stopping'].includes(t.status),approval:t=>t.status==='awaiting_approval',review:t=>t.status==='awaiting_review'}[state.tab]||(()=>true);
 return state.items.tasks.filter(t=>tab(t)&&(state.toolFilter==='all'||t.tool===state.toolFilter)&&(!state.search||(t.title+' '+idOf(t)).toLowerCase().includes(state.search.toLowerCase())));
}
function rail(){
 const byTool={};
 for(const c of state.items.connections){const key=c.tool;byTool[key]??={cap:0,used:0};byTool[key].cap+=Number(c.maxConcurrency)||1}
 for(const t of state.items.tasks)if(['running','planning','stopping'].includes(t.status)){byTool[t.tool]??={cap:0,used:0};byTool[t.tool].used++}
 const caps=Object.entries(byTool).map(([tool,v])=>{const pct=v.cap?Math.min(100,Math.round(v.used/v.cap*100)):0;return `<div class="capacity"><div class="capacityline">${toolIcon(tool)}<span>${v.used} / ${v.cap||'—'}</span></div><div class="bar ${tool==='codex'&&v.used>=v.cap&&v.cap?'orange':''}"><i style="width:${pct}%"></i></div></div>`}).join('')||'<div class="tiny">接入工具连接后显示并发。</div>';
 const nodes=state.items.nodes.map(n=>`<div class="nodeitem"><span class="dot ${n.status==='online'?'':'gray'}"></span><span>${escapeHTML(n.name)}</span><small>${n.status==='online'?'在线':'离线'}</small></div>`).join('')||'<div class="tiny">还没有执行节点。</div>';
 const events=state.items.audit.slice(0,4).map(a=>`<div class="event"><p><b>${escapeHTML(a.actorName||'')}</b> ${escapeHTML(a.action||'')}</p><time>${escapeHTML(a.createdAt?new Date(a.createdAt).toLocaleString():'')}</time></div>`).join('')||'<div class="tiny">还没有调度记录。</div>';
 return `<div class="railsection"><div class="railheading">当前工具负载</div>${caps}</div><div class="railsection"><div class="railheading">执行节点</div>${nodes}</div><div class="railsection"><div class="railheading">最近调度</div>${events}</div>`;
}
function projectsPage(){return title('项目','管理仓库、基础分支与成员可见范围。','<button class="primary" data-action="new-project">＋ 添加项目</button>')+(state.items.projects.length?`<div class="cards">${state.items.projects.map(p=>`<article class="card"><div class="split-title"><h2>${escapeHTML(p.name)}</h2>${tag(p.visibility||'private',p.visibility==='private'?'':'blue')}</div><p class="sub">${escapeHTML(p.repoUrl||'')}${p.baseBranch?' · '+escapeHTML(p.baseBranch):''}</p><div class="notice">${scopeText(p)} · 仓库访问仍需执行节点本地授权。</div><div class="row" style="margin-top:15px"><button data-project-tasks="${escapeHTML(idOf(p))}">查看任务</button></div></article>`).join('')}</div>`:empty('先添加一个项目','连接 Git 仓库和基础分支。任务将只在已授权的项目范围内执行。','<button class="primary" data-action="new-project">添加项目</button>'))}
function scopeText(x){if(x.visibility==='team')return '团队共享';if(x.visibility==='custom')return `${(x.memberIds||[]).length} 位指定成员`;return '仅自己可见'}
function connectionsPage(){
 const owned=state.items.nodes.filter(n=>n.ownerId===state.user.id);
 const canCreate=owned.length>0;
 const cards=state.items.connections.map(c=>{
  const node=nodeOf(c.nodeId);
  const owner=memberName(c.ownerId);
  return `<article class="panel toolcard"><div class="toolcardhead">${toolIcon(c.tool)}${tag(scopeText(c),c.visibility==='private'?'':'blue')}</div><h2>${escapeHTML(c.name)}</h2><div class="sub">${escapeHTML(owner)} · ${escapeHTML(node?.name||'执行节点')}</div><div class="kv"><span>默认模型</span><b>${escapeHTML(c.model||'未配置')}</b></div><div class="kv"><span>思考模式</span><span>${escapeHTML(c.mode||'工具默认')}</span></div><div class="tiny">${c.allowOverride?'任务可在授权范围内调整模型':'任务固定使用连接默认值'} · 并发 ${escapeHTML(c.maxConcurrency||1)} · ${c.allowAutoFailover?'允许自动接管':'仅手动转交'}</div><div class="toolcardfooter">${c.ownerId===state.user.id?`<button class="small" data-edit-connection="${escapeHTML(idOf(c))}">模型配置</button>`:'<span class="tiny">由连接所有者管理</span>'}</div></article>`;
 }).join('');
 const emptyCard=!state.items.nodes.length?empty('先连接执行节点','节点上报已安装的工具和模型。登录凭据留在节点本机。','<button data-action="new-node">添加执行节点</button>'):empty('还没有工具连接',canCreate?'从节点实际上报的模型里选择默认值和思考模式。':'等节点所有者创建连接，或使用已共享的连接。',canCreate?'<button class="primary" data-action="new-connection">接入工具</button>':'');
 return title('工具连接','账号默认私有。共享使用权，凭据保留在所属执行节点。',canCreate?'<button class="primary" data-action="new-connection">＋ 接入工具</button>':'')+`<div class="banner"><span>连接权限与项目权限分别校验。共享任务不会自动共享工具账号。</span><button class="quiet" data-page="members">查看共享规则 →</button></div>`+(cards?`<div class="cards">${cards}</div>`:emptyCard);
}
function nodesPage(){return title('执行节点','执行节点从本机主动连接控制台，不需要公网 IP、入站端口或 SSH。远程机器需能访问控制台 URL。','<button class="primary" data-action="new-node">＋ 注册节点</button>')+(state.items.nodes.length?`<section class="panel wrap"><table><thead><tr><th>节点</th><th>状态</th><th>可见范围</th><th>最后心跳</th><th>已发现工具</th><th></th></tr></thead><tbody>${state.items.nodes.map(n=>{const status=nodeStatus(n);return `<tr><td><b>${escapeHTML(n.name)}</b><div class="tiny">${escapeHTML(n.platform||'')}</div></td><td>${tag(status==='pending'?'待首次连接':statusName(status),statusColor(status))}</td><td>${scopeText(n)}</td><td>${escapeHTML(n.onlineAt?new Date(n.onlineAt).toLocaleString():'等待首次连接')}</td><td>${escapeHTML((n.tools||[]).join(', ')||'等待能力上报')}</td><td><button class="small" data-node-detail="${escapeHTML(idOf(n))}">详情</button></td></tr>`}).join('')}</tbody></table></section>`:empty('暂无执行节点','创建注册信息后，目标电脑会主动连回控制台；无需填写节点 IP 或端口。','<button class="primary" data-action="new-node">注册第一个节点</button>'))+(state.selectedNode?nodeDetailModal(): '')}
function nodeDetailModal(){const n=findById(state.items.nodes,state.selectedNode);if(!n)return'';const status=nodeStatus(n),projects=(n.projectIds||[]).map(id=>findById(state.items.projects,id)?.name||id);const caps=n.capabilities?.tools||[];return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${escapeHTML(n.name)}</h2><button class="quiet" data-action="close-node-detail">✕</button></div><div class="modal-body"><p>${tag(status==='pending'?'待首次连接':statusName(status),statusColor(status))}</p><div class="kv"><span>最后心跳</span><b>${escapeHTML(n.onlineAt?new Date(n.onlineAt).toLocaleString():'尚未连接')}</b></div><div class="kv"><span>授权项目</span><b>${escapeHTML(projects.join('、')||'无')}</b></div><h3>节点实际上报的能力</h3>${caps.length?caps.map(t=>`<div class="callout"><b>${escapeHTML(toolLabel(t.tool))}</b><div class="tiny">${escapeHTML((t.models||[]).map(m=>m.name||m.id).join('、')||'未报告模型')}</div></div>`).join(''):'<div class="callout">尚未上报工具和模型。请在节点本机完成 CLI 登录并启动节点进程。</div>'}<div class="notice">重连：在节点本机设置 GAS_TOWN_NODE_TOKEN，然后用原配置运行 npm run node -- --config /绝对路径/node-config.json。令牌丢失后不能从控制台取回；撤销旧节点并重新注册。</div></div><div class="modal-foot"><button data-action="close-node-detail">关闭</button></div></section></div>`}
function membersPage(){return title('成员与共享','资源默认私有。添加团队成员后，可以分别授权项目、连接与执行节点。','<button data-action="new-team">创建团队</button><button class="primary" data-action="new-member">＋ 添加成员</button>')+`<section class="panel"><div class="panel-head"><h2>组织成员</h2></div>${state.items.members.length?`<div class="wrap"><table><thead><tr><th>成员</th><th>角色</th><th>加入时间</th></tr></thead><tbody>${state.items.members.map(m=>`<tr><td>${escapeHTML(m.name)}<div class="tiny">${escapeHTML(m.email)}</div></td><td>${escapeHTML(m.role||'member')}</td><td>${escapeHTML(m.createdAt?new Date(m.createdAt).toLocaleDateString():'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有其他成员','管理员可以添加成员。添加账号不会自动授权私人资源。')}</section><section class="panel"><div class="panel-head"><h2>团队</h2><span class="tiny">共享规则按团队执行</span></div>${state.items.teams.length?`<div class="wrap"><table><thead><tr><th>团队</th><th>成员数量</th><th>成员</th></tr></thead><tbody>${state.items.teams.map(t=>`<tr><td>${escapeHTML(t.name)}</td><td>${(t.memberIds||t.members||[]).length}</td><td>${escapeHTML((t.memberNames||[]).join('、')||'成员列表由授权接口控制')}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有团队','创建团队后，可以把项目、连接或节点分享给组内成员。')}</section><section class="panel"><div class="panel-head"><h2>共享的连接</h2></div>${state.items.connections.some(c=>c.visibility!=='private')?`<div class="wrap"><table><thead><tr><th>连接</th><th>连接所有者</th><th>共享范围</th><th>自动接管</th></tr></thead><tbody>${state.items.connections.filter(c=>c.visibility!=='private').map(c=>`<tr><td>${escapeHTML(c.name)}</td><td>${escapeHTML(c.ownerName||'')}</td><td>${scopeText(c)}</td><td>${c.allowAutoFailover?'已允许':'未允许'}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无共享连接','连接所有者可在工具连接设置里授权团队或指定成员。')}</section>`}
function auditPage(){return title('操作记录','查看任务分配、工具转交与共享授权的完整轨迹。')+(state.items.audit.length?`<section class="panel wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>对象</th><th>记录</th></tr></thead><tbody>${state.items.audit.map(a=>{const detail=a.details&&typeof a.details==='object'?Object.entries(a.details).map(([k,v])=>k+': '+v).join(' · '):(a.details||'');return `<tr><td>${escapeHTML(a.createdAt?new Date(a.createdAt).toLocaleString():'')}</td><td>${escapeHTML(a.actorName||'')}</td><td>${escapeHTML(a.action||'')}</td><td>${escapeHTML(a.objectId||'')}</td><td>${escapeHTML(detail)}</td></tr>`}).join('')}</tbody></table></section>`:empty('还没有操作记录','创建项目、添加连接或下发任务后，相关动作会显示在这里。'))}
function taskDetail(){
 const task=state.detail;if(!task)return `<button data-page="tasks">← 返回任务</button>`;
 const plan=Array.isArray(task.plan)?task.plan:task.plan?.steps||[];
 const events=task.events||[];
 const attempts=task.attempts||[];
 const project=findById(state.items.projects,task.projectId);
 const conn=connectionOf(task.connectionId);
 const node=nodeOf(conn?.nodeId);
 const canApprove=task.status==='awaiting_approval';
 const transfer=canTransfer(task)?'<button data-action="transfer">转交工具</button>':'';
 const approve=canApprove?'<button class="primary" data-action="approve">确认计划并开工</button>':'';
 const tabs=[['plan','执行计划'],['activity','实时执行'],['changes','代码与产出'],['history','调度记录']];
 const body={
  plan:`${task.plan?.summary?`<p class="sub">${escapeHTML(task.plan.summary)}</p>`:''}${plan.length?plan.map((step,i)=>`<div class="phase"><span class="phasecircle">${i+1}</span><div><h3>${escapeHTML(step.title||'')}</h3><div class="tiny">${escapeHTML(step.acceptance||'')}</div></div></div>`).join(''):'<div class="notice">计划生成后会显示步骤和验收条件。确认前不会开始写代码。</div>'}${canApprove?'<div class="notice">确认计划时再选择是否允许推送分支和创建 PR。合并始终由人决定。</div>':''}`,
  activity:events.length?`<div class="timeline">${[...events].reverse().map(e=>`<div class="event"><p><b>${escapeHTML(statusName(e.type)||e.type)}</b> ${escapeHTML(e.message||'')}</p><time>${escapeHTML(e.createdAt?new Date(e.createdAt).toLocaleString():'')}</time></div>`).join('')}</div>`:'<div class="notice">节点报告日志、计划或测试结果后显示在这里。不根据日志估算完成百分比。</div>',
  changes:`<div class="detailmeta"><div><label>分支</label>${escapeHTML(task.handoffCheckpoint?.branch||'等待节点确认')}</div><div><label>工作区</label>${escapeHTML(task.handoffCheckpoint?.worktree||'执行节点本地工作区')}</div><div><label>未提交改动</label>${task.handoffCheckpoint? (task.handoffCheckpoint.dirty?'有':'无') :'尚未交接'}</div><div><label>推送 / PR</label>${task.allowPush?'已授权推送':'未授权推送'} · ${task.allowPr?'已授权创建 PR':'未授权创建 PR'}</div></div>${githubPrLink(task.result?.prUrl||task.prUrl||events.findLast?.(e=>e.data?.prUrl)?.data?.prUrl)}<div class="notice">合并由人决定。页面只展示节点实际上报的结果。</div>`,
  history:events.length?events.map(e=>`<div class="event"><p><b>${escapeHTML(e.type||'')}</b> ${escapeHTML(e.message||'')}</p><time>${escapeHTML(e.createdAt?new Date(e.createdAt).toLocaleString():'')}</time></div>`).join(''):'<div class="notice">分配、确认和转交会记在这里。</div>'
 }[state.detailTab]||'';
 const attemptsTable=attempts.length?`<section class="panel" style="margin-top:18px"><div class="panelhead"><h2>执行尝试</h2></div><div class="wrap"><table><thead><tr><th>类型</th><th>模型</th><th>状态</th><th>开始</th></tr></thead><tbody>${attempts.map(a=>`<tr><td>${escapeHTML(a.kind||'')}</td><td>${escapeHTML(a.model||'')} · ${escapeHTML(a.mode||'')}</td><td>${tag(statusName(a.status),statusColor(a.status))}</td><td>${escapeHTML(a.startedAt?new Date(a.startedAt).toLocaleString():'—')}</td></tr>`).join('')}</tbody></table></div></section>`:'';
 return `<button class="quiet" data-page="tasks" style="padding-left:0">← 返回任务中心</button>${title(escapeHTML(task.title||'任务'),`${escapeHTML(shortId(idOf(task)))} · ${escapeHTML(project?.name||'')}`,`${tag(statusName(task.status),statusColor(task.status))} ${transfer}${approve}`)}<div class="split"><section class="panel"><div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${state.detailTab===k?'active':''}" data-detailtab="${k}">${l}</button>`).join('')}</div><div class="pad">${body}</div></section><aside><section class="panel pad"><h2>执行上下文</h2><div class="detailmeta"><div><label>工具</label>${toolIcon(task.tool)}</div><div><label>连接</label>${escapeHTML(conn?.name||'—')}</div><div><label>模型</label>${escapeHTML(task.model||'连接默认')}</div><div><label>思考模式</label>${escapeHTML(task.mode||'连接默认')}</div><div><label>执行节点</label>${escapeHTML(node?.name||'等待分配')}</div><div><label>负责人</label>${escapeHTML(memberName(task.ownerId))}</div></div></section></aside></div>${attemptsTable}`;
}
function renderModal(){
 const type=state.modal;if(!type)return'';
 if(type==='token')return nodeSetupModal();
 const content=type==='new-task'?taskForm():type==='new-project'?projectForm():type==='new-node'?nodeForm():type==='new-connection'?connectionForm():type==='edit-connection'?connectionForm(state.editing):type==='new-member'?memberForm():type==='new-team'?teamForm():type==='approve'?`<div class="callout">批准当前执行计划后才会启动执行节点。推送和创建 PR 需要单独勾选，合并不会被授权。</div><label class="check"><input name="allowPush" type="checkbox">允许推送任务分支</label><label class="check"><input name="allowPR" type="checkbox">允许创建 PR，不包括合并</label>`:type==='transfer'?transferForm():type==='policy'?`<div class="notice" style="margin-top:0">自动接管按每条工具连接的授权执行。连接所有者勾选“允许自动接管”后，额度耗尽的任务才能改派到这条连接。读不到真实额度时，页面不会假装知道剩余额度。</div><p class="sub">手动转交随时可用，前提是目标连接在同一台执行节点，并且你有使用权。</p>`:'';
 const heading=({ 'new-task':'下发一个新需求','new-project':'添加项目','new-node':'注册执行节点','new-connection':'接入工具','edit-connection':'模型与思考模式','new-member':'添加成员','new-team':'创建团队','approve':'确认计划并开工','transfer':'转交执行工具','policy':'接管策略'})[type]||'设置';
 const submit=({ 'new-task':'生成执行计划','new-project':'保存项目','new-node':'注册节点并显示令牌','new-connection':'创建工具连接','edit-connection':'保存模型配置','new-member':'创建成员','new-team':'创建团队','approve':'确认并排队执行','transfer':'确认停止并转交','policy':''})[type];
 return `<div class="modal-backdrop" data-backdrop><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${heading}</h2><div class="sub">${type==='new-task'?'确认前只生成计划，不启动开发任务。':''}</div></div><button class="quiet" data-action="close-modal" aria-label="关闭">✕</button></div><form id="modal-form" class="modal-body form">${content}<div id="modal-error" role="alert"></div></form><div class="modal-foot"><span class="tiny">${type==='policy'?'规则保存在各工具连接上':'数据按已授权范围校验'}</span><div class="actions">${type==='policy'?'<button class="primary" data-action="close-modal">知道了</button>':`<button data-action="close-modal">取消</button><button form="modal-form" class="primary">${submit}</button>`}</div></div></section></div>`
}
function options(items,placeholder,label=x=>x.name||idOf(x)){return `<option value="">${placeholder}</option>${items.map(x=>`<option value="${escapeHTML(idOf(x))}">${escapeHTML(label(x))}</option>`).join('')}`}
function sharingFields(prefix,initial='private'){return `<div class="field"><label for="${prefix}-visibility">可见范围</label><select id="${prefix}-visibility" name="visibility"><option value="private" ${initial==='private'?'selected':''}>仅自己（默认）</option><option value="team" ${initial==='team'?'selected':''}>指定团队</option><option value="custom" ${initial==='custom'?'selected':''}>自定义成员</option></select></div><div id="${prefix}-sharing-extra">${sharingExtra(prefix,initial)}</div>`}
function sharingExtra(prefix,scope,current={}){if(scope==='team')return `<div class="field"><label>选择团队</label><select name="teamId" required>${state.items.teams.map(t=>`<option value="${escapeHTML(idOf(t))}" ${idOf(t)===current.teamId?'selected':''}>${escapeHTML(t.name)}</option>`).join('')||'<option value="">请先创建团队</option>'}</select></div>`;if(scope==='custom')return `<fieldset class="field" style="border:0;padding:0;margin:0"><legend class="label">允许的成员</legend>${state.items.members.map(m=>`<label class="check"><input type="checkbox" name="memberIds" value="${escapeHTML(idOf(m))}" ${(current.memberIds||[]).includes(idOf(m))?'checked':''}>${escapeHTML(m.name)} (${escapeHTML(m.email)})</label>`).join('')||'<div class="tiny">请先添加成员。</div>'}</fieldset>`;return '<p class="tiny">仅创建者可见。</p>'}
function projectForm(){return `<div class="two">${field('name','项目名称')}${field('baseBranch','基础分支','main')}</div>${field('repoUrl','Git 仓库地址','', 'url')}<p class="tiny">仓库地址用于标识项目；实际文件访问由执行节点本地路径映射和权限控制。</p>${sharingFields('project')}`}
function memberForm(){return `<div class="two">${field('name','姓名')}${field('email','邮箱','','email')}</div>${field('password','初始密码','','password')}<div class="callout">密码仅在此处提交一次。成员首次登录后应在私有部署设置的认证流程中更换密码。</div>`}
function teamForm(){return `${field('name','团队名称')}<fieldset class="field" style="border:0;padding:0;margin:0"><legend class="label">团队成员</legend>${state.items.members.map(m=>`<label class="check"><input type="checkbox" name="memberIds" value="${escapeHTML(idOf(m))}">${escapeHTML(m.name)} (${escapeHTML(m.email)})</label>`).join('')}</fieldset><div class="callout">团队成员只在资源明确选择此团队后，才能访问对应资源。</div>`}
function nodeForm(){return `<div class="two">${field('name','节点名称')}<div class="field"><label for="node-kind">节点类型</label><select name="kind" id="node-kind"><option value="personal">个人电脑</option><option value="team">团队执行节点</option></select></div></div>${sharingFields('node')}<fieldset class="field" style="border:0;padding:0;margin:0"><legend class="label">允许该节点访问的项目</legend>${state.items.projects.map(p=>`<label class="check"><input type="checkbox" name="projectIds" value="${escapeHTML(idOf(p))}">${escapeHTML(p.name)}</label>`).join('')||'<div class="tiny">请先添加项目。</div>'}</fieldset><div class="callout">令牌创建后只显示一次。注册时不要把令牌放进网址、聊天或代码仓库。</div>`}
function setupConfig(){const setup=state.nodeSetup;if(!setup)return{};return buildNodeConfig({serverUrl:document.querySelector('#node-server-url')?.value||'',projects:setup.projects.map(project=>({...project,id:idOf(project),repoPath:document.querySelector(`[data-repo="${CSS.escape(idOf(project))}"]`)?.value||''})),cliPaths:Object.fromEntries(['codex','cursor'].map(tool=>[tool,document.querySelector(`[data-cli="${tool}"]`)?.value||'']))})}
function nodeSetupModal(){const setup=state.nodeSetup;if(!setup)return'';const config=setupConfig(),json=JSON.stringify(config,null,2),ready=validateNodeConfig(config).valid;return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">节点注册成功：完成本机安装</h2><div class="sub">${escapeHTML(setup.node?.name||'节点')} · 当前状态：待首次连接</div></div><button class="quiet" data-action="close-modal" aria-label="关闭">✕</button></div><div class="modal-body"><div class="callout">这台机器会主动向控制台发起 HTTPS 请求，不需要 IP、端口映射或 SSH。远程节点必须能访问这里填写的控制台地址；localhost 只适用于同一台机器。不要猜测或使用未验证的公网地址。</div><div class="field"><label for="node-server-url">控制台 URL</label><input id="node-server-url" value="${escapeHTML(location.origin)}" placeholder="https://console.example.com" required></div><div class="tiny">当前默认来自浏览器地址 ${escapeHTML(location.origin)}。只有目标节点能访问此地址时才可使用。</div><h3>项目本地路径映射</h3>${setup.projects.map(p=>`<div class="panel pad"><b>${escapeHTML(p.name)}</b><div class="tiny">项目 ID：${escapeHTML(idOf(p))}</div><div class="field"><label>节点电脑上的绝对仓库路径</label><input data-repo="${escapeHTML(idOf(p))}" placeholder="/Users/name/Projects/repo" required></div><div class="tiny">基础分支：${escapeHTML(p.baseBranch||'main')}</div></div>`).join('')}<h3>节点上已安装并登录的 CLI</h3><p class="tiny">填节点电脑上的可执行文件绝对路径；通过 which codex / which agent 查找。CLI 账号必须已在该电脑登录。</p><div class="two"><div class="field"><label>Codex CLI 路径（可选）</label><input data-cli="codex" placeholder="/opt/homebrew/bin/codex"></div><div class="field"><label>Cursor Agent CLI 路径（可选）</label><input data-cli="cursor" placeholder="/opt/homebrew/bin/agent"></div></div><p class="label">只显示一次的节点令牌（不写入配置文件）</p><div class="token">${escapeHTML(state.token)}</div><button class="small" data-action="copy-token">复制令牌</button><h3>配置文件预览（不含令牌）</h3><pre id="node-config-preview" class="callout">${escapeHTML(json)}</pre><button class="small" data-action="download-node-config" ${ready?'':'disabled'}>下载 node-config.json</button><div class="callout warning"><b>节点电脑操作</b><ol><li>安装 Node.js 24+、Git，并安装/登录所需 CLI。</li><li>在 Gastown 控制台仓库目录安装依赖：<code>npm ci</code>。这一步需要在节点电脑取得仓库代码。</li><li>把下载的 JSON 放到该仓库目录，并将权限设为仅本人可读：<code>chmod 600 node-config.json</code></li><li>在 Gastown 仓库目录安全输入令牌并运行只读预检：<code>read -s GAS_TOWN_NODE_TOKEN; export GAS_TOWN_NODE_TOKEN; npm run node -- --config "$PWD/node-config.json" --check</code></li><li>预检通过后，使用相同命令但移除 <code>--check</code> 才会启动 worker 并领取任务。</li></ol><p>read 命令会隐藏输入。预检会验证配置、项目仓库和 CLI，并测试控制台心跳；预检不领取任务，但可能让节点短暂显示在线。令牌只放入该节点进程环境，不要写到配置 JSON、脚本、聊天或代码仓库。页面不会假设远程程序已安装。</p></div><button class="small" data-action="copy-node-start">复制启动说明</button><div class="notice">当首次心跳成功后，节点会显示在线和实际检测到的工具、模型。关闭此窗口后令牌不再显示；丢失时需撤销并重新注册。</div></div><div class="modal-foot"><span class="tiny">配置就绪：${ready?'可以下载':'请填写有效 URL、绝对路径，并至少配置一个 CLI'}</span><button class="primary" data-action="close-token">完成</button></div></section></div>`}
function connectionForm(connection){const nodes=state.items.nodes.filter(n=>n.ownerId===state.user.id||idOf(n)===state.user.id);const base=connection||{};return `<div class="two"><div class="field"><label for="connection-node">执行节点</label><select id="connection-node" name="nodeId" required>${options(nodes,'选择在线节点',n=>`${n.name} · ${statusName(n.status)}`)}</select></div><div class="field"><label for="connection-tool">工具</label><select id="connection-tool" name="tool" required><option value="">先选执行节点</option></select></div></div><div id="connection-capabilities" class="callout">选择执行节点后读取它上报的模型能力。</div><div class="two"><div class="field"><label for="connection-model">默认模型</label><select id="connection-model" name="model" required disabled><option value="">等待能力清单</option></select></div><div class="field"><label for="connection-mode">默认思考模式</label><select id="connection-mode" name="mode" required disabled><option value="">先选择模型</option></select></div></div>${field('name','连接名称',base.name||'')}<div class="field"><label>可用于任务的模型</label><div id="allowed-models" class="tiny">先选择模型。</div></div><label class="check"><input type="checkbox" name="allowOverride" ${base.allowOverride?'checked':''}>允许任务单独选择已授权模型与思考模式</label>${sharingFields('connection',base.visibility||'private')}<div class="two"><div class="field"><label>最大并发任务数</label><input name="maxConcurrency" type="number" min="1" max="16" value="${escapeHTML(base.maxConcurrency||1)}" required></div><label class="check"><input type="checkbox" name="allowAutoFailover" ${base.allowAutoFailover?'checked':''}>允许项目策略自动接管</label></div><fieldset class="field" style="border:0;padding:0;margin:0"><legend class="label">授权项目</legend>${state.items.projects.map(p=>`<label class="check"><input type="checkbox" name="projectIds" value="${escapeHTML(idOf(p))}" ${(base.projectIds||[]).includes(idOf(p))?'checked':''}>${escapeHTML(p.name)}</label>`).join('')||'<div class="tiny">请先添加项目。</div>'}</fieldset>`}
function taskForm(){return `<div class="two"><div class="field"><label for="task-project">项目</label><select name="projectId" id="task-project" required>${options(state.items.projects,'选择项目')}</select></div><div class="field"><label for="task-connection">执行连接</label><select name="connectionId" id="task-connection" required>${options(state.items.connections.filter(c=>c.status!=='offline'),'选择可用连接',c=>`${c.name} · ${c.tool}`)}</select></div></div>${field('title','任务名称')}<div class="field"><label for="description">需求与验收条件</label><textarea id="description" name="description" required></textarea></div><div class="two"><div class="field"><label for="task-model">模型</label><select id="task-model" name="model" disabled><option value="">使用连接默认值</option></select></div><div class="field"><label for="task-mode">思考模式</label><select id="task-mode" name="mode" disabled><option value="">使用连接默认值</option></select></div></div><div id="task-config-note" class="callout">新任务先进入规划队列。执行模型与模式受连接所有者的权限限制。</div><label class="check"><input name="autoFailover" id="task-auto-failover" type="checkbox" disabled>额度耗尽时允许系统自动改派到其他已授权连接</label><div id="task-failover-note" class="tiny">默认关闭。选择明确允许自动接管的来源连接后才能启用。</div>`}
function transferForm(){const ids=state.transferIds.length?state.transferIds:(state.detail?[idOf(state.detail)]:[]);const tasks=ids.map(id=>state.items.tasks.find(t=>idOf(t)===id)||(state.detail&&idOf(state.detail)===id?state.detail:null)).filter(Boolean);const nodeId=taskNodeId(tasks[0]||{});const sourceTools=new Set(tasks.map(t=>t.tool));const targets=state.items.connections.filter(c=>c.nodeId===nodeId&&!sourceTools.has(c.tool));const node=nodeOf(nodeId);return `<div class="handoffsummary">${[...sourceTools].map(toolIcon).join('')}<span style="color:#a4adbb">→</span><span class="sub">同一节点接手</span></div><div class="callout warning">将停止 ${tasks.length} 个任务的原执行者。节点确认停止并保留工作区后，目标工具才启动。跨机器转交当前不可用。</div><div class="field"><label for="transfer-connection">目标连接${node?` · ${escapeHTML(node.name)}`:''}</label><select id="transfer-connection" name="connectionId" required>${options(targets,'选择已授权目标',c=>`${c.name} · ${toolLabel(c.tool)} · ${c.model}`)}</select></div><div class="notice">接手使用目标连接的模型和思考模式，不沿用来源工具的参数。完整聊天记录不能迁移。</div>${targets.length?'':'<div class="tiny">这台节点上没有其他已授权工具连接。</div>'}`}
function renderError(error){root.innerHTML=`<main class="center panel"><h1>无法连接团队控制台</h1><div class="callout error">${escapeHTML(error.message||'读取服务状态失败')}</div><p class="sub">确认控制台服务正在运行，然后重试。</p><button class="primary" data-action="retry">重试</button></main>`;bind()}
function bind(){
 root.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>{state.page=button.dataset.page;state.detail=null;state.modal=null;render()}));
 root.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>action(button.dataset.action)));
 root.querySelectorAll('[data-task]').forEach(button=>button.addEventListener('click',()=>openTask(button.dataset.task)));
 root.querySelectorAll('[data-project-tasks]').forEach(button=>button.addEventListener('click',()=>{state.page='tasks';state.search='';render()}));
 const search=document.querySelector('#task-search');if(search)search.oninput=()=>{state.search=search.value;const pos=search.selectionStart;render();const next=document.querySelector('#task-search');if(next){next.focus();next.setSelectionRange(pos,pos)}};
 const toolFilter=document.querySelector('#tool-filter');if(toolFilter)toolFilter.onchange=()=>{state.toolFilter=toolFilter.value;state.selected.clear();render()};
 root.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{state.tab=button.dataset.tab;state.selected.clear();render()});
 root.querySelectorAll('[data-detailtab]').forEach(button=>button.onclick=()=>{state.detailTab=button.dataset.detailtab;render()});
 root.querySelectorAll('[data-select]').forEach(box=>box.onchange=()=>{box.checked?state.selected.add(box.dataset.select):state.selected.delete(box.dataset.select);render()});
 root.querySelectorAll('[data-edit-connection]').forEach(button=>button.onclick=()=>{const connection=state.items.connections.find(c=>idOf(c)===button.dataset.editConnection);if(!connection||connection.ownerId!==state.user.id){toast('只有连接所有者可以修改配置。',true);return}state.editing=button.dataset.editConnection;state.modal='edit-connection';render();wireConnectionForm()});
 root.querySelectorAll('[data-node-detail]').forEach(button=>button.onclick=()=>{state.selectedNode=button.dataset.nodeDetail;render()});
 root.querySelectorAll('[data-action="close-node-detail"]').forEach(button=>button.onclick=()=>{state.selectedNode=null;render()});
 if(state.modal==='token'){
  const refreshPreview=()=>{const preview=document.querySelector('#node-config-preview');if(preview)preview.textContent=JSON.stringify(setupConfig(),null,2)};
  root.querySelectorAll('#node-server-url,[data-repo],[data-cli]').forEach(input=>input.addEventListener('input',refreshPreview));
  root.querySelectorAll('[data-action="download-node-config"]').forEach(button=>button.onclick=()=>{const config=setupConfig();if(!validateNodeConfig(config).valid){toast('请先填写可访问的 HTTPS/本机 URL、绝对项目路径和至少一条绝对 CLI 路径。',true);return}const blob=new Blob([JSON.stringify(config,null,2)+'\n'],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='node-config.json';link.click();URL.revokeObjectURL(link.href)});
  root.querySelectorAll('[data-action="copy-node-start"]').forEach(button=>button.onclick=async()=>{await navigator.clipboard.writeText(`npm ci\nread -s GAS_TOWN_NODE_TOKEN; export GAS_TOWN_NODE_TOKEN\nnpm run node -- --config "$PWD/node-config.json" --check\n# 预检通过后移除 --check 再运行以启动 worker`);toast('启动说明已复制。请将配置路径替换为节点电脑上的绝对路径。')});
 }
 const form=document.querySelector('#modal-form');if(form){form.addEventListener('submit',submitModal);wireSharing('project');wireSharing('node');wireSharing('connection');wireTaskForm();if(state.modal==='new-connection')wireConnectionForm();}
}
async function openTask(id){try{state.detail=await api('/tasks/'+encodeURIComponent(id));state.page='detail';render()}catch(error){toast(error.message,true)}}
function openModal(name){state.modal=name;state.editing=null;state.capabilities=null;render();if(name==='new-connection')wireConnectionForm()}
function wireSharing(prefix){const control=document.querySelector('#'+prefix+'-visibility');if(control)control.onchange=()=>{const current=prefix==='connection'?state.items.connections.find(c=>idOf(c)===state.editing):{};document.querySelector('#'+prefix+'-sharing-extra').innerHTML=sharingExtra(prefix,control.value,current||{})}}
function connectionTemplate(){const connection=state.items.connections.find(c=>idOf(c)===state.editing);const html=connectionForm(connection);return html}
async function wireConnectionForm(){
 const form=document.querySelector('#modal-form');if(!form)return;
 if(state.editing){const connection=state.items.connections.find(c=>idOf(c)===state.editing);if(connection){const formElement=document.querySelector('#connection-node');if(formElement)formElement.value=connection.nodeId}}
 const nodeSelect=document.querySelector('#connection-node'),toolSelect=document.querySelector('#connection-tool');if(!nodeSelect||!toolSelect)return;
 async function loadNode(nodeId){const hint=document.querySelector('#connection-capabilities');toolSelect.innerHTML='<option value="">读取节点工具…</option>';toolSelect.disabled=true;if(hint)hint.textContent='正在读取执行节点能力…';try{state.capabilities=await api('/capabilities?nodeId='+encodeURIComponent(nodeId));const tools=state.capabilities.tools||[],connection=state.items.connections.find(c=>idOf(c)===state.editing);toolSelect.innerHTML=tools.length?tools.map(x=>`<option value="${escapeHTML(x.tool)}" ${x.tool===connection?.tool?'selected':''}>${escapeHTML(x.tool)}</option>`).join(''):'<option value="">该节点尚未上报工具</option>';toolSelect.disabled=tools.length===0;if(hint)hint.textContent=tools.length?'以下模型由所选节点实际发现；更换节点或 CLI 版本后可能变化。':'节点尚未报告可用模型。请先运行节点并完成工具登录。';fillConnectionModels();}catch(error){if(hint)hint.innerHTML=`<span class="callout error">${escapeHTML(error.message)}</span>`;toolSelect.innerHTML='<option value="">能力读取失败</option>';toolSelect.disabled=true}}
 nodeSelect.onchange=()=>loadNode(nodeSelect.value);toolSelect.onchange=fillConnectionModels;
 if(nodeSelect.value)await loadNode(nodeSelect.value);
}
function fillConnectionModels(){
 const tool=document.querySelector('#connection-tool')?.value;
 const source=(state.capabilities?.tools||[]).find(x=>x.tool===tool),models=source?.models||[];
 const model=document.querySelector('#connection-model'),mode=document.querySelector('#connection-mode');if(!model||!mode)return;
 const connection=state.items.connections.find(c=>idOf(c)===state.editing);model.innerHTML=models.map(m=>`<option value="${escapeHTML(m.id)}" ${m.id===connection?.model?'selected':''}>${escapeHTML(m.name)}</option>`).join('');model.disabled=models.length===0;mode.disabled=models.length===0;
 if(!models.length){model.innerHTML='<option value="">节点未上报模型</option>';mode.innerHTML='<option value="">思考模式不可用</option>';document.querySelector('#allowed-models').textContent='节点未报告模型。';return}
 model.onchange=()=>fillModes(models);fillModes(models);
 document.querySelector('#allowed-models').innerHTML=models.map(m=>`<label class="check"><input type="checkbox" name="allowedModels" value="${escapeHTML(m.id)}" ${(connection?.allowedModels||[]).length?(connection.allowedModels||[]).includes(m.id):true}>允许任务使用 ${escapeHTML(m.name)}</label>`).join('');
}
function fillModes(models){const selected=models.find(m=>m.id===document.querySelector('#connection-model')?.value),select=document.querySelector('#connection-mode');if(!select||!selected)return;const connection=state.items.connections.find(c=>idOf(c)===state.editing);select.innerHTML=(selected.modes||[]).map(x=>`<option value="${escapeHTML(x)}" ${x===connection?.mode?'selected':''}>${escapeHTML(x)}</option>`).join('');select.disabled=!(selected.modes||[]).length;if(!selected.modes?.length)select.innerHTML='<option value="">此模型未提供思考模式</option>'}
function wireTaskForm(){const connection=document.querySelector('#task-connection');if(!connection)return;let serial=0;const update=async()=>{const request=++serial,c=state.items.connections.find(x=>idOf(x)===connection.value),model=document.querySelector('#task-model'),mode=document.querySelector('#task-mode'),note=document.querySelector('#task-config-note'),autoFailover=document.querySelector('#task-auto-failover'),failoverNote=document.querySelector('#task-failover-note');if(autoFailover){autoFailover.disabled=!c?.allowAutoFailover;if(!c?.allowAutoFailover)autoFailover.checked=false}if(failoverNote)failoverNote.textContent=c?.allowAutoFailover?'此连接所有者已授权自动接管；是否对本任务启用由你决定。':'来源连接未授权自动接管，或尚未选择连接。';if(!model||!mode)return;if(!c){model.disabled=mode.disabled=true;model.innerHTML='<option value="">先选择连接</option>';mode.innerHTML='<option value="">先选择连接</option>';return}model.disabled=mode.disabled=true;model.innerHTML='<option value="">读取连接模型…</option>';mode.innerHTML='<option value="">读取连接模式…</option>';let models=[];try{const catalog=await api('/capabilities?nodeId='+encodeURIComponent(c.nodeId));if(request!==serial)return;models=(catalog.tools||[]).find(x=>x.tool===c.tool)?.models||[]}catch(error){if(note)note.textContent='无法读取连接模型清单：'+error.message;return}if(request!==serial)return;const allowed=new Set(c.allowedModels||[]),available=models.filter(m=>allowed.has(m.id));model.innerHTML=available.map(m=>`<option value="${escapeHTML(m.id)}" ${m.id===c.model?'selected':''}>${escapeHTML(m.name)}</option>`).join('')||`<option value="">${escapeHTML(c.model||'由连接默认值决定')}</option>`;const selected=available.find(m=>m.id===model.value)||available.find(m=>m.id===c.model);function setModes(m){const modes=m?.modes||[];mode.innerHTML=modes.map(x=>`<option value="${escapeHTML(x)}" ${x===c.mode?'selected':''}>${escapeHTML(x)}</option>`).join('')||`<option value="">${escapeHTML(c.mode||'由连接默认值决定')}</option>`}setModes(selected);model.disabled=mode.disabled=!c.allowOverride||available.length===0;model.onchange=()=>setModes(available.find(m=>m.id===model.value));if(note)note.textContent=c.allowOverride?'模型清单来自此连接所在节点。任务选项受连接所有者授权限制。':'任务固定使用连接默认模型与思考模式。'};connection.onchange=()=>update();update()}
function formValues(form){const data=new FormData(form),out={};for(const [key,value]of data.entries()){if(key==='memberIds'||key==='projectIds'||key==='allowedModels'){out[key]??=[];out[key].push(value)}else out[key]=value}form.querySelectorAll('input[type=checkbox][name]').forEach(input=>{if(!input.checked&&!['memberIds','projectIds','allowedModels'].includes(input.name))out[input.name]=false});for(const key of ['allowOverride','allowAutoFailover'])if(out[key]===undefined)out[key]=false;if(out.maxConcurrency!==undefined)out.maxConcurrency=Number(out.maxConcurrency);if(out.projectIds===undefined&&form.querySelector('[name=projectIds]'))out.projectIds=[];if(out.memberIds===undefined&&form.querySelector('[name=memberIds]'))out.memberIds=[];if(out.allowedModels===undefined&&form.querySelector('[name=allowedModels]'))out.allowedModels=[];delete out.confirm;delete out.kind;return out}
async function submitModal(event){event.preventDefault();const form=event.currentTarget,values=formValues(form),error=document.querySelector('#modal-error');if(error)error.innerHTML='';const submit=form.parentElement.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
 let result;
 if(state.modal==='new-task'){const body={...values,autoFailover:!!values.autoFailover};if(!body.model)delete body.model;if(!body.mode)delete body.mode;result=await api('/tasks',{method:'POST',body});state.modal=null;state.page='tasks';await refresh();const id=idOf(result.task||result);if(id)await openTask(id);else render();toast('任务已提交规划；执行会等待你确认计划。')}
 else if(state.modal==='new-project'){result=await api('/projects',{method:'POST',body:values});state.modal=null;await refresh();render();toast('项目已保存。')}
 else if(state.modal==='new-node'){if(!values.projectIds?.length)throw new Error('请至少授权一个项目给节点。');result=await api('/nodes',{method:'POST',body:values});const token=result.token||result.node?.token;if(!token)throw new Error('节点已创建，但服务器没有返回一次性令牌。请检查节点详情与审计记录。');state.token=token;state.nodeSetup={node:result.node||result,projects:values.projectIds.map(id=>findById(state.items.projects,id)).filter(Boolean)};state.modal='token';await refresh();render()}
 else if(state.modal==='new-connection'||state.modal==='edit-connection'){if(!values.allowedModels?.includes(values.model))throw new Error('默认模型必须包含在连接授权模型中。');const path=state.editing?'/connections/'+encodeURIComponent(state.editing):'/connections';await api(path,{method:state.editing?'PATCH':'POST',body:values});state.modal=null;state.editing=null;await refresh();render();toast('工具连接已保存。')}
 else if(state.modal==='new-member'){await api('/members',{method:'POST',body:values});state.modal=null;await refresh();render();toast('成员账号已创建。')}
 else if(state.modal==='new-team'){await api('/teams',{method:'POST',body:values});state.modal=null;await refresh();render();toast('团队已创建。')}
 else if(state.modal==='approve'){const body={allowPush:!!values.allowPush,allowPR:!!values.allowPR};await api('/tasks/'+encodeURIComponent(idOf(state.detail))+'/approve',{method:'POST',body});state.modal=null;await openTask(idOf(state.detail));toast('计划已批准，任务进入执行队列。')}
 else if(state.modal==='transfer'){if(!values.connectionId)throw new Error('请选择目标连接。');const ids=state.transferIds.length?state.transferIds:[idOf(state.detail)];for(const id of ids)await api('/tasks/'+encodeURIComponent(id)+'/transfer',{method:'POST',body:{connectionId:values.connectionId}});state.modal=null;state.selected.clear();state.transferIds=[];await refresh();if(ids.length===1)await openTask(ids[0]);else{state.page='tasks';render()}toast('停止请求已发送。目标工具会在原执行者停下后接手。')}
 }catch(err){if(error)error.innerHTML=`<div class="callout error">${escapeHTML(err.message)}</div>`;else toast(err.message,true)}finally{if(submit)submit.disabled=false}}
async function action(name){try{if(name==='logout'){await api('/auth/logout',{method:'POST'});state.user=null;state.csrf='';renderAuth(false);return}if(name==='refresh'||name==='retry'){await refresh();render();return}if(name==='new-task'){if(!state.items.projects.length)throw new Error('请先添加一个项目。');if(!state.items.connections.length)throw new Error('请先接入执行节点和工具连接。');openModal(name);return}if(name==='new-project'||name==='new-node'||name==='new-connection'||name==='new-member'||name==='new-team'){openModal(name);return}if(name==='approve'){state.modal='approve';render();return}if(name==='transfer'){state.transferIds=[idOf(state.detail)];state.modal='transfer';render();return}if(name==='transfer-selected'||name==='quick-transfer'){const ids=name==='quick-transfer'?state.items.tasks.filter(t=>t.status==='quota_blocked').map(idOf):[...state.selected];if(!ids.length)throw new Error('没有可转交的任务。');const nodes=new Set(ids.map(id=>taskNodeId(state.items.tasks.find(t=>idOf(t)===id))));if(nodes.size>1)throw new Error('所选任务不在同一台执行节点上，不能一起转交。');state.transferIds=ids;state.modal='transfer';render();return}if(name==='open-policy'){state.modal='policy';render();return}if(name==='close-modal'||name==='close-token'){if(state.modal==='token'||name==='close-token'){state.token=null;state.nodeSetup=null}state.modal=null;render();return}if(name==='copy-token'){await navigator.clipboard.writeText(state.token);toast('令牌已复制；请立即保存在节点本机。');return}}catch(error){toast(error.message,true)}}
document.addEventListener('click',event=>{if(event.target.matches('[data-backdrop]')){state.modal=null;render()}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.modal){state.modal=null;state.token=null;render()}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user&&!state.modal)poll()});
async function poll(){if(document.hidden||state.modal||!state.user)return;try{if(state.page==='detail'&&state.detail){state.detail=await api('/tasks/'+encodeURIComponent(idOf(state.detail)));render()}else if(state.page==='tasks'){await refresh();render()}}catch(error){toast(error.message,true)}}
setInterval(poll,4500);
boot();
